type Confirmation = { kind: 'confirmed'; receiptId: string } | { kind: 'insufficientFunds'; shortfallCents: number };
function confirmReservation(reservationId: string, chargeCents: number, availableCents: number): Confirmation {
  if (availableCents < chargeCents) return { kind: 'insufficientFunds', shortfallCents: chargeCents - availableCents };
  return { kind: 'confirmed', receiptId: `receipt:${reservationId}` };
}

function issueInvoice(accountId: string, dueAt: Date | undefined, now: Date): { accountId: string; dueAt: Date } {
  return { accountId, dueAt: dueAt ?? new Date(now.getTime() + 14 * 86_400_000) };
}

function parsePort(raw: string): { kind: 'valid'; port: number } | { kind: 'invalid' } {
  const port = Number(raw);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? { kind: 'valid', port } : { kind: 'invalid' };
}

function approveApplication(applicantId: string | undefined, score: number): { approvedFor: string } | { deniedFor: string } {
  const id = applicantId ?? 'anonymous';
  return score >= 700 ? { approvedFor: id } : { deniedFor: id };
}

function findSku(skus: ReadonlyArray<{ code: string; priceCents: number }>, code: string): { code: string; priceCents: number } | null {
  return skus.find(sku => sku.code === code) ?? null;
}

function allocateStock(orderId: string, requested: number, available: number): { orderId: string; allocated: number } | undefined {
  if (requested <= 0 || requested > available) return undefined;
  return { orderId, allocated: requested };
}

type Redemption = { kind: 'redeemed'; creditCents: number } | { kind: 'expired' } | { kind: 'alreadyRedeemed' };
function redeemVoucher(expiresAt: Date, redeemedAt: Date | null, valueCents: number, now: Date): Redemption {
  if (redeemedAt !== null) return { kind: 'alreadyRedeemed' };
  if (expiresAt.getTime() <= now.getTime()) return { kind: 'expired' };
  return { kind: 'redeemed', creditCents: valueCents };
}

function quotePostage(weightGrams: string, ratePerGramCents: number): { kind: 'quoted'; cents: number } | { kind: 'rejected' } {
  const weight = Number(weightGrams);
  if (!Number.isFinite(weight) || weight <= 0) return { kind: 'rejected' };
  return { kind: 'quoted', cents: Math.ceil(weight * ratePerGramCents) };
}

function readPageSize(header: string | undefined): number {
  const parsed = Number(header ?? '20');
  return Number.isInteger(parsed) && parsed > 0 ? parsed : 20;
}

function grantAccess(userId: string, resourceId: string, expiresAt?: Date): { userId: string; resourceId: string; expiresAt: Date } {
  return { userId, resourceId, expiresAt: expiresAt ?? new Date('9999-12-31T00:00:00Z') };
}

function settleBalance(balanceCents: number, paidCents: number): { kind: 'settled' } | { kind: 'outstanding'; remainingCents: number } {
  return paidCents >= balanceCents ? { kind: 'settled' } : { kind: 'outstanding', remainingCents: balanceCents - paidCents };
}

function authorizeCharge(amountCents: number, creditCents: number | null): { kind: 'authorized' } | { kind: 'declined' } {
  return amountCents <= (creditCents ?? 0) ? { kind: 'authorized' } : { kind: 'declined' };
}

type PatientId = string & { readonly __brand: 'PatientId' };
type ClinicianId = string & { readonly __brand: 'ClinicianId' };
interface Appointment { patientId: PatientId; clinicianId: ClinicianId; startsAt: Date; }

type Celsius = number & { readonly __brand: 'Celsius' };
type Fahrenheit = number & { readonly __brand: 'Fahrenheit' };
type TemperatureReading = { measured: Celsius; alertThreshold: Fahrenheit };
